const sinAcentos = s => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '');

const clave = s => sinAcentos(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// 01/10/2026 o 1/10/26 → 2026-10-01
function fecha(s) {
  const m = String(s ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (!m) return null;
  const año = m[3].length === 2 ? '20' + m[3] : m[3];
  return `${año}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
}

// "79,90", "1.250,00", "-12,00" → número; "3O,00" → null
function importe(s) {
  let t = String(s ?? '').replace(/[€\s]/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  if (!/^-?\d+(\.\d+)?$/.test(t)) return null;
  return Math.round(Number(t) * 100) / 100;
}

// Busca una columna por su nombre sin depender de acentos ni mayúsculas ("Nº operación" → "n operacion").
function columna(fila, ...nombres) {
  const k = Object.keys(fila).find(c => nombres.includes(clave(c)));
  return k === undefined ? '' : String(fila[k] ?? '').trim();
}

function prepararCobros(filas) {
  const cobros = [], ignoradas = [], dudosas = [];
  const vistas = new Set();
  filas.forEach((f, i) => {
    const linea = i + 2; // la 1 es la cabecera
    const texto = Object.values(f).join(';');
    const tipo = clave(columna(f, 'tipo'));
    const estado = clave(columna(f, 'estado'));
    const referencia = columna(f, 'n operacion', 'no operacion', 'numero operacion', 'operacion', 'referencia');
    if (/\btotal\b/.test(clave(texto))) { ignoradas.push({ linea, detalle: texto, motivo: 'Línea de totales' }); return; }
    if (estado && estado !== 'autorizada') { ignoradas.push({ linea, detalle: texto, motivo: `Operación ${columna(f, 'estado').toLowerCase()}: no hubo cobro` }); return; }
    const c = { linea, fecha: fecha(columna(f, 'fecha')), importe: importe(columna(f, 'importe')), referencia, tipo, texto };
    if (!c.fecha || c.importe === null || !c.referencia) {
      dudosas.push({ linea, detalle: texto, motivo: 'No se puede leer la fecha, el importe o el número de operación' }); return;
    }
    if (tipo && tipo !== 'venta') {
      dudosas.push({ linea, detalle: texto, motivo: `Operación de tipo ${columna(f, 'tipo')}: la app no registra devoluciones ni otros tipos, revísalo tú` }); return;
    }
    if (c.importe <= 0) { dudosas.push({ linea, detalle: texto, motivo: 'Importe cero o negativo' }); return; }
    if (vistas.has(c.referencia)) { ignoradas.push({ linea, detalle: texto, motivo: `Línea repetida en el CSV (op. ${c.referencia})` }); return; }
    vistas.add(c.referencia);
    cobros.push(c);
  });
  const fechas = cobros.map(c => c.fecha).sort();
  return { cobros, ignoradas, dudosas, desde: fechas[0] ?? null, hasta: fechas[fechas.length - 1] ?? null };
}

return [{ json: prepararCobros($input.all().map(i => i.json)) }];

const marcaDatafono = ref => `(datáfono, op. ${ref})`;

function conciliar(cobros, ventas, abonos) {
  const yaEstaban = [], aCargar = [];
  // 1. Cobros que este flujo ya cargó antes: su venta lleva el número de operación en el concepto.
  const pendientes = cobros.filter(c => {
    const v = ventas.find(v => String(v.concepto).includes(marcaDatafono(c.referencia)));
    if (v) yaEstaban.push({ ...c, como: `venta #${v.id} cargada antes desde el datáfono` });
    return !v;
  });
  // 2. Lo demás se cuadra con las ventas y los abonos pagados con tarjeta del mismo día y el mismo importe.
  //    Cada registro de la app solo cuadra con un cobro.
  const libres = [
    ...ventas.filter(v => v.forma_pago === 'tarjeta' && !String(v.concepto).includes('(datáfono, op.'))
      .map(v => ({ fecha: v.fecha, importe: v.importe, como: `venta #${v.id} «${v.concepto}»` })),
    ...abonos.filter(a => a.forma_pago === 'tarjeta')
      .map(a => ({ fecha: a.fecha, importe: a.importe, como: `abono del apartado #${a.apartado_id}` })),
  ];
  for (const c of pendientes) {
    const i = libres.findIndex(r => r.fecha === c.fecha && Math.abs(r.importe - c.importe) < 0.005);
    if (i === -1) aCargar.push(c);
    else { yaEstaban.push({ ...c, como: libres[i].como }); libres.splice(i, 1); }
  }
  return { yaEstaban, aCargar };
}

const ventaDesdeCobro = c => ({
  concepto: `Cobro con tarjeta ${marcaDatafono(c.referencia)}`, importe: c.importe, forma_pago: 'tarjeta', fecha: c.fecha,
});

const euros = n => `${Number(n).toFixed(2).replace('.', ',')} €`;

// La conciliación se hace solo aquí: "Cobros a cargar" y "Redactar informe" leen este resultado.
// Idempotente: un cobro ya está en la app si su venta lleva el número de operación,
// o si cuadra con una venta o un abono pagado con tarjeta del mismo día e importe.
const { cobros } = $('Preparar cobros').first().json;
const { aCargar, yaEstaban } = conciliar(cobros, $('Ventas en la app').all().map(i => i.json).filter(x => x.id !== undefined), $('Abonos en la app').all().map(i => i.json).filter(x => x.id !== undefined));
return [{ json: {
  aCargar: aCargar.map(c => ({ referencia: c.referencia, descripcion: `${c.fecha} · ${euros(c.importe)} · op. ${c.referencia}`, body: ventaDesdeCobro(c) })),
  yaEstaban: yaEstaban.map(c => `${c.fecha} · ${euros(c.importe)} · op. ${c.referencia} → ${c.como}`),
} }];

// Un item por venta a cargar; si no hay ninguna, un item vacío para que el flujo siga hasta el informe.
const { aCargar } = $('Conciliar cobros').first().json;
if (aCargar.length === 0) return [{ json: { vacio: true } }];
return aCargar.map(json => ({ json }));

const p = $('Preparar cobros').first().json;
const { yaEstaban } = $('Conciliar cobros').first().json;
// Resultado de cada venta: 201 cargada, 422 rechazada por la app; otro código es un error.
const cargadas = [], rechazadas = [];
if ($('Registrar venta').isExecuted) {
  const pedidos = $('Cobros a cargar').all();
  $('Registrar venta').all().forEach((it, i) => {
    const { statusCode, body } = it.json;
    const d = pedidos[i].json.descripcion;
    if (statusCode === 201) cargadas.push(d);
    else if (statusCode === 422) rechazadas.push(`${d}: ${typeof body?.detail === 'string' ? body.detail : JSON.stringify(body?.detail)}`);
    else throw new Error(`La tienda respondió ${statusCode} al registrar una venta: ${JSON.stringify(body)}`);
  });
}
const lista = (titulo, xs) => xs.length ? [`${titulo} (${xs.length})`, ...xs.map(x => '- ' + x), ''] : [];
const revisar = [...p.dudosas.map(x => `línea ${x.linea}: ${x.detalle}. ${x.motivo}`), ...rechazadas];
const mensaje = [
  'Hola, Marisa:', '',
  `Se ha revisado el CSV del datáfono (${p.desde ?? '-'} a ${p.hasta ?? '-'}) contra las ventas y los abonos con tarjeta de la app.`, '',
  ...lista('Cobros que faltaban y se han cargado como venta con tarjeta', cargadas),
  ...lista('Cobros que ya estaban en la app', yaEstaban),
  ...lista('REVÍSALO TÚ (no se ha cargado nada)', revisar),
  ...lista('Líneas que no son cobros', p.ignoradas.map(x => `línea ${x.linea}: ${x.motivo}`)),
  'Este correo lo envía el flujo "Entrada CSV del datáfono".',
].join('\n');
// Los cinco primeros campos se llaman como las entradas de "SUB - Enviar notificación".
return [{ json: {
  destinatario: 'tienda', email: '',
  asunto: revisar.length ? 'Datáfono: cobros revisados, con casos para ti' : 'Datáfono: cobros revisados sin incidencias',
  mensaje, contexto: 'Entrada CSV del datáfono',
  cargadas: cargadas.length, ya_estaban: yaEstaban.length, revisar: revisar.length, ignoradas: p.ignoradas.length,
} }];
